@inline function imei(::Type{BigFloat}, m::Integer, i::Integer, j::Integer, k::Integer)
    n = ((m * 2 + i) * 5 + j) * 27 + k + 1
    return BigFloat(@inbounds IMEI_NUM[n])/BigFloat(@inbounds IMEI_DEN[n])
end
